INSERT INTO locations (id, warehouse, zone, rack, shelf, position, type, parent_location_id, is_active)
SELECT md5('q1-location:' || s.location_key), s.warehouse, s.zone, s.rack, s.shelf, s.position,
  s.location_type::location_type,
  CASE WHEN s.parent_key IS NULL THEN NULL ELSE md5('q1-location:' || s.parent_key) END,
  true
FROM seed s
ON CONFLICT (id) DO NOTHING;
